package net.atlasauth.pca.verifier

import java.nio.file.Files
import java.nio.file.Path
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Differential against the TS reference packages/pca/src/intent-acc.ts: test-data/k042-intentacc.json is generated by
 * tools/pca-audit/java-mutate/k042-intentacc-oracle.mjs; every case asserts the EXACT reason / verdict / value (canonical JSON).
 */
class K042IntentAccOracleTest {
    companion object {
        @Suppress("UNCHECKED_CAST")
        val cases: List<Map<String, Any?>> by lazy {
            (Json.parseLenient(String(Files.readAllBytes(Path.of("test-data/k042-intentacc.json")), Charsets.UTF_8)) as List<Map<String, Any?>>)
        }
        @Suppress("UNCHECKED_CAST") fun args(c: Map<String, Any?>) = c["args"] as List<Any?>
        fun m(o: Any?) = IntentJs.obj(o)
        fun s(o: Any?) = o as String
        fun d(o: Any?) = IntentJs.num(o)!!

        fun toJson(o: Any?): Any? = when (o) {
            is Long, is Int -> Json.Num(o.toString())
            is IntentAcc.AccValue -> {
                val r = LinkedHashMap<String, Any?>()
                if (o.reason != null) {
                    r["ok"] = false; r["reason"] = o.reason
                    if (o.value != 0L || o.key != null) r["leaked"] = "${o.value}/${o.key}"
                } else { r["ok"] = true; r["val"] = Json.Num(o.value.toString()); r["key"] = o.key }
                r
            }
            else -> o
        }

        fun run(fn: String, f: (List<Any?>) -> Any?) {
            val bad = ArrayList<String>(); var n = 0
            for (c in cases) {
                if (fn != c["fn"]) continue
                n++
                val got: Any? = try { f(args(c)) } catch (e: RuntimeException) { "THREW $e" }
                val want = Json.canonicalize(c["out"]); val g = Json.canonicalize(toJson(got))
                if (want != g) bad.add("${c["name"]}\n    want $want\n    got  $g")
            }
            assertTrue("no cases for $fn", n > 0)
            assertTrue("${bad.size}/$n $fn cases differ from the TS reference:\n  " + bad.take(40).joinToString("\n  "), bad.isEmpty())
        }
        fun caseArgs(name: String) = args(cases.first { it["name"] == name })
    }

    @Test fun corpusLoaded() = assertTrue(cases.size > 1500)
    @Test fun accumulatorDeclError() = run("accumulatorDeclError") { IntentAcc.accumulatorDeclError(it[0]) }
    @Test fun monitorDeclError() = run("monitorDeclError") { IntentAcc.monitorDeclError(it[0]) }
    @Test fun monitorStates() = run("monitorStates") { IntentAcc.monitorStates(m(it[0])) }
    @Test fun trackedKeySetError() = run("trackedKeySetError") { IntentAcc.trackedKeySetError(it[0]) }

    @Test fun preState() {
        run("preStateError") { IntentAcc.preStateError(it[0], it[1]) }
        run("preValue") { IntentAcc.preValue(it[0], m(it[1])) }
        run("combineAcc") { a ->
            IntentAcc.combineAcc(a[0], m(a[1]), IntentAcc.AccValue(null, IntentJs.lng(IntentJs.get(a[2], "val")), IntentJs.get(a[2], "key") as String?))
        }
    }

    @Test fun selectionAndValues() {
        run("accSelects") { IntentAcc.accSelects(m(it[0]), s(it[1]), it[2]) }
        run("accValueOf") { IntentAcc.accValueOf(m(it[0]), s(it[1]), m(it[2]), it[3]) }
    }

    @Test fun receiptArithmeticOk() = run("receiptArithmeticOk") { IntentAcc.receiptArithmeticOk(it[0], m(it[1]), IntentJs.lng(it[2])) }
    @Test fun pcactnReservationDigest() = run("pcactnReservationDigest") { IntentAcc.pcactnReservationDigest(m(it[0])) }
    @Test fun receiptShapeError() = run("receiptShapeError") { IntentAcc.receiptShapeError(it[0]) }
    @Test fun keySetShapeError() = run("keySetShapeError") { IntentAcc.keySetShapeError(it[0]) }
    @Test fun verifyKeySet() = run("verifyKeySet") { IntentAcc.verifyKeySet(it[0], s(it[1]), it[2], it[3] as Boolean) }
    @Test fun verifyReceiptSignature() = run("verifyReceiptSignature") { a ->
        if (a[0] is Map<*, *>) IntentAcc.verifyReceiptSignature(m(a[0]), s(a[1]), if (a[2] == null) null else m(a[2])) else false
    }
    @Test fun verifyReceiptAgainstHolder() = run("verifyReceiptAgainstHolder") {
        IntentAcc.verifyReceiptAgainstHolder(m(it[0]), m(it[1]), it[2], d(it[3]), d(it[4]), d(it[5]), it[6])
    }

    @Test fun monitorStatesOfAnUnknownKindIsEmpty() {
        assertEquals(emptyList<String>(), IntentAcc.monitorStates(m(Json.parseLenient("{\"kind\":\"other\"}"))))
        assertEquals(emptyList<String>(), IntentAcc.monitorStates(m(Json.parseLenient("{}"))))
    }

    @Test fun verifyKeySetPinsOnlyWhenTheRootPqKeyIsPresent() {
        val pq = caseArgs("verifyKeySet/pq-pinned")
        assertTrue(IntentAcc.verifyKeySet(pq[0], s(pq[1]), pq[2], true))
        assertFalse(IntentAcc.verifyKeySet(pq[0], s(pq[1]), pq[2], false))
        val ok = caseArgs("verifyKeySet/ok")
        assertTrue(IntentAcc.verifyKeySet(ok[0], s(ok[1]), null, false))
    }
}
